/* oxlint-disable typescript/strict-boolean-expressions -- Normalizer patterns and AST fixture nodes are untyped generated-source data. */
import { parse } from "acorn";
import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { readdirSync } from "node:fs";

import { normalizeGeneratedLoader } from "./generated-loader-normalization.mjs";

const root = new URL("../", import.meta.url);
const generatedTypecheckOptOut =
  "// @ts-nocheck -- generated by @napi-rs/cli";
const runtimePackages = [
  "@emnapi/core",
  "@emnapi/runtime",
  "@napi-rs/wasm-runtime",
];
const read = (path) =>
  readFileSync(new URL(path, root), "utf8");

const extractFunction = (source, name) => {
  const start = source.indexOf(`function ${name}(`);
  if (start < 0) throw new Error(`${name} not found`);
  const body = source.indexOf("{", start);
  let depth = 0;
  for (let index = body; index < source.length; index++) {
    if (source[index] === "{") depth++;
    if (source[index] !== "}") continue;
    depth--;
    if (depth === 0) return source.slice(start, index + 1);
  }
  throw new Error(`${name} is incomplete`);
};

const schedulerNames = new Set([
  "__scheduleMacrotask",
  "__scheduleTimer",
  "setTimeout",
  "setImmediate",
  "queueMicrotask",
]);
const schedulerDefinitionNames = new Set([
  "__armWasmRuntimePollStallBackup",
  "__invokeWasmCleanupPollScheduler",
  "__scheduleTimer",
  "__wasiSetImmediate",
]);

const schedulerCallsOutsideHandshake = (source) => {
  const ast = parse(source, {
    ecmaVersion: "latest",
    sourceType: "module",
  });
  const aliasCandidates = new Map();
  const visitAliases = (node) => {
    if (!node || typeof node !== "object") return;
    if (
      node.type === "VariableDeclarator" &&
      node.id?.type === "Identifier" &&
      (schedulerNames.has(node.init?.name) ||
        (node.init?.type === "MemberExpression" &&
          !node.init.computed &&
          schedulerNames.has(node.init.property?.name)))
    ) {
      aliasCandidates.set(node.id.name, [
        ...(aliasCandidates.get(node.id.name) ?? []),
        true,
      ]);
    } else if (
      node.type === "VariableDeclarator" &&
      node.id?.type === "Identifier"
    ) {
      aliasCandidates.set(node.id.name, [
        ...(aliasCandidates.get(node.id.name) ?? []),
        false,
      ]);
    }
    for (const [key, value] of Object.entries(node)) {
      if (key === "start" || key === "end") continue;
      if (Array.isArray(value)) {
        for (const child of value) visitAliases(child);
      } else {
        visitAliases(value);
      }
    }
  };
  visitAliases(ast);
  const aliases = new Set(schedulerNames);
  for (const [name, declarations] of aliasCandidates) {
    if (declarations.every(Boolean)) aliases.add(name);
  }

  const violations = [];
  const scheduleMacrotaskDefinition = ast.body.find(
    (node) =>
      node.type === "VariableDeclaration" &&
      node.declarations.some(
        (declaration) =>
          declaration.id.name === "__scheduleMacrotask",
      ),
  );
  const visitCalls = (
    node,
    ancestors,
    inSchedulerDefinition,
  ) => {
    if (!node || typeof node !== "object") return;
    const entersNamedDefinition =
      node.type === "FunctionDeclaration" &&
      schedulerDefinitionNames.has(node.id?.name);
    const definition =
      inSchedulerDefinition ||
      entersNamedDefinition ||
      node === scheduleMacrotaskDefinition;
    if (!definition && node.type === "CallExpression") {
      const isNamedScheduler =
        node.callee.type === "Identifier" &&
        aliases.has(node.callee.name);
      const isMessagePost =
        node.callee.type === "MemberExpression" &&
        !node.callee.computed &&
        node.callee.property?.name === "postMessage" &&
        source
          .slice(node.callee.start, node.callee.end)
          .includes(".port");
      if (isNamedScheduler || isMessagePost) {
        const guarded = ancestors.some(
          (ancestor) =>
            ancestor.type === "CallExpression" &&
            ancestor.callee?.type === "Identifier" &&
            ancestor.callee.name ===
              "__invokeWasmCleanupPollScheduler",
        );
        if (!guarded) {
          violations.push(
            source.slice(node.start, node.end),
          );
        }
      }
    }
    const nextAncestors = [...ancestors, node];
    for (const [key, value] of Object.entries(node)) {
      if (key === "start" || key === "end") continue;
      if (Array.isArray(value)) {
        for (const child of value)
          visitCalls(child, nextAncestors, definition);
      } else {
        visitCalls(value, nextAncestors, definition);
      }
    }
  };
  visitCalls(ast, [], false);
  return violations;
};

const workerConstructionsWithoutSharedData = (source) => {
  const ast = parse(source, {
    ecmaVersion: "latest",
    sourceType: "module",
  });
  const declarations = new Map();
  const workers = [];
  const visit = (node) => {
    if (!node || typeof node !== "object") return;
    if (
      node.type === "VariableDeclarator" &&
      node.id?.type === "Identifier"
    ) {
      declarations.set(node.id.name, node.init);
    }
    if (
      node.type === "NewExpression" &&
      node.callee?.type === "Identifier" &&
      node.callee.name === "Worker"
    ) {
      workers.push(node);
    }
    for (const [key, value] of Object.entries(node)) {
      if (key === "start" || key === "end") continue;
      if (Array.isArray(value)) {
        for (const child of value) visit(child);
      } else {
        visit(value);
      }
    }
  };
  visit(ast);

  const dataSources = new Set();
  const violations = [];
  for (const worker of workers) {
    const optionsArgument = worker.arguments[1];
    const options =
      optionsArgument?.type === "Identifier"
        ? declarations.get(optionsArgument.name)
        : optionsArgument;
    const workerDataProperty = options?.properties?.find(
      (property) =>
        !property.computed &&
        property.key?.name === "workerData",
    );
    if (workerDataProperty?.value?.type !== "Identifier") {
      violations.push(
        source.slice(worker.start, worker.end),
      );
      continue;
    }
    const dataSource = declarations.get(
      workerDataProperty.value.name,
    );
    if (dataSource?.type !== "ObjectExpression") {
      violations.push(
        source.slice(worker.start, worker.end),
      );
      continue;
    }
    dataSources.add(workerDataProperty.value.name);
  }
  if (dataSources.size > 1) {
    violations.push("multiple workerData sources");
  }
  return violations;
};

describe("generated loader normalization", () => {
  test("keeps the generated typecheck opt-out while removing other directives", () => {
    const source = `/* eslint-disable */
// @ts-nocheck -- generated by @napi-rs/cli
// prettier-disable generated output
const binding = load()
`;
    expect(
      normalizeGeneratedLoader(source, {
        keepGeneratedTypecheckOptOut: true,
      }),
    ).toBe(`${generatedTypecheckOptOut}
const binding = load()
`);
  });

  for (const fileName of [
    "aho-corasick.wasi-browser.js",
    "aho-corasick.wasi.cjs",
  ]) {
    test(`${fileName} retries live cleanup after scheduling throws`, async () => {
      const source = read(fileName);
      expect(source).toContain(generatedTypecheckOptOut);
      const schedulerHandshake = extractFunction(
        source,
        "__invokeWasmCleanupPollScheduler",
      );
      const scheduleTimer = extractFunction(
        source,
        "__scheduleTimer",
      );
      const yieldTurn = extractFunction(
        source,
        "__yieldWasmRuntimePollTurn",
      );
      const prepare = extractFunction(
        source,
        "__prepareWasmEnvCleanupWithTurns",
      );
      // oxlint-disable-next-line typescript/no-implied-eval -- Executes functions extracted from the real generated loader.
      const createHarness = Function(`${schedulerHandshake}
${scheduleTimer}
${yieldTurn}
${prepare}
let __emnapiWasmEnvCleanupPrepared = false
let __emnapiWasmEnvCleanupPreparing = false
let __emnapiWasmEnvCleanupRan = false
let __emnapiWasmEnvCleanupYielding = false
let __finishParkedWasmEnvCleanup
let workIsPending = true
let schedulerThrows = true
let finishCount = 0
const __WASM_RUNTIME_WORK_POLL_INTERVAL_MS = 0
const __WASM_RUNTIME_WORK_POLL_TRUSTED_ARRIVALS = 2
const __napiInstance = { exports: {
  napi_prepare_wasm_env_cleanup_begin: () => true,
  napi_prepare_wasm_env_cleanup_finish: () => { finishCount++ },
  napi_wasm_runtime_work_pending: () => workIsPending,
} }
const __createWasmRuntimePollPace = () => ({ arrivals: 0 })
const __armWasmRuntimePollStallBackup = () => {}
const globalThis = { setTimeout: undefined }
const __prepareWasmEnvCleanup = () => {}
const __abortWasiDisposalIfThreadCrashed = () => {}
const __scheduleMacrotask = (callback) => {
  callback()
  if (schedulerThrows) throw new Error("scheduling failed")
}
return {
  prepare: __prepareWasmEnvCleanupWithTurns,
  recover: () => { schedulerThrows = false; workIsPending = false },
  state: () => ({ finishCount, preparing: __emnapiWasmEnvCleanupPreparing,
    parked: __finishParkedWasmEnvCleanup, workIsPending }),
}`);
      const harness = createHarness();

      // oxlint-disable-next-line typescript/await-thenable, typescript/no-confusing-void-expression -- Function-created fixture types are opaque to the type-aware linter.
      await expect(harness.prepare()).rejects.toThrow(
        "scheduling failed",
      );
      expect(harness.state()).toMatchObject({
        finishCount: 0,
        preparing: false,
        workIsPending: true,
      });
      expect(harness.state().parked).toBeFunction();

      harness.recover();
      await harness.prepare();
      expect(harness.state()).toEqual({
        finishCount: 1,
        preparing: false,
        parked: undefined,
        workIsPending: false,
      });
    });

    test(`${fileName} reports a timer throw after its callback ran`, () => {
      const source = read(fileName);
      const scheduleTimer = extractFunction(
        source,
        "__scheduleTimer",
      );
      // oxlint-disable-next-line typescript/no-implied-eval -- Executes a function extracted from the real generated loader.
      const run = Function(`${scheduleTimer}
let fallbackCalls = 0
const __scheduleMacrotask = () => { fallbackCalls++ }
const globalThis = { setTimeout: (callback) => {
  callback()
  throw new Error("timer failed after callback")
} }
return () => {
  let callbackCalls = 0
  let error
  try { __scheduleTimer(() => { callbackCalls++ }, 0) } catch (caught) { error = caught }
  return { callbackCalls, fallbackCalls, error }
}`)();

      const result = run();
      expect(result.callbackCalls).toBe(1);
      expect(result.fallbackCalls).toBe(0);
      expect(result.error).toBeInstanceOf(Error);
      expect(result.error.message).toBe(
        "timer failed after callback",
      );
    });

    test(`${fileName} bounds a failed async-work drain and retries`, async () => {
      const source = read(fileName);
      const schedulerHandshake = extractFunction(
        source,
        "__invokeWasmCleanupPollScheduler",
      );
      const scheduleTimer = extractFunction(
        source,
        "__scheduleTimer",
      );
      const drain = extractFunction(
        source,
        "__drainWasiAsyncWork",
      );
      // oxlint-disable-next-line typescript/no-implied-eval -- Executes functions extracted from the real generated loader.
      const createHarness = Function(`${schedulerHandshake}
${scheduleTimer}
${drain}
let __wasiAsyncWorkDrainPromise
let pending = 1
let schedulerThrows = true
let cancelCalls = 0
const __WASI_ASYNC_WORK_POLL_INTERVAL_MS = 1
const __keepEventLoopAliveUntil = (work) => work
const globalThis = { setTimeout: undefined, WebAssembly }
const __scheduleMacrotask = (callback) => {
  callback()
  if (schedulerThrows) throw new Error("macrotask failed after callback")
}
const __napiInstance = { exports: {
  napi_wasm_async_work_pending: () => pending,
  napi_wasm_cancel_pending_async_work: () => { cancelCalls++ },
} }
return {
  drain: __drainWasiAsyncWork,
  recover: () => { schedulerThrows = false; pending = 0 },
  cancelCalls: () => cancelCalls,
}`);
      const harness = createHarness();
      const boundedDrain = Promise.race([
        harness.drain(),
        new Promise((_, reject) =>
          setTimeout(
            () => reject(new Error("drain timed out")),
            100,
          ),
        ),
      ]);

      // oxlint-disable-next-line typescript/await-thenable, typescript/no-confusing-void-expression -- Function-created fixture types are opaque to the type-aware linter.
      await expect(boundedDrain).rejects.toThrow(
        "macrotask failed after callback",
      );
      expect(harness.cancelCalls()).toBe(1);
      harness.recover();
      harness.drain();
      expect(harness.cancelCalls()).toBe(1);
    });

    test(`${fileName} handles every poll scheduler behaviour`, async () => {
      const source = read(fileName);
      const schedulerHandshake = extractFunction(
        source,
        "__invokeWasmCleanupPollScheduler",
      );
      const yieldTurn = extractFunction(
        source,
        "__yieldWasmRuntimePollTurn",
      );
      const prepare = extractFunction(
        source,
        "__prepareWasmEnvCleanupWithTurns",
      );
      const behaviours = [
        "unavailable",
        "async-return",
        "sync-return",
        "sync-throw-after",
        "throw-before",
      ];
      const throwingBehaviours = new Set([
        "unavailable",
        "sync-throw-after",
        "throw-before",
      ]);
      // oxlint-disable-next-line typescript/no-implied-eval -- Executes functions extracted from each real generated loader.
      const createHarness = Function(
        "nativeSetTimeout",
        "timerBehaviour",
        "macrotaskBehaviour",
        "requiredTurns",
        `${schedulerHandshake}
${yieldTurn}
${prepare}
let __emnapiWasmEnvCleanupPrepared = false
let __emnapiWasmEnvCleanupPreparing = false
let __emnapiWasmEnvCleanupRan = false
let __emnapiWasmEnvCleanupYielding = false
let __finishParkedWasmEnvCleanup
let finishCount = 0
let healthyTurns = 0
let timerCalls = 0
let macrotaskCalls = 0
const __WASM_RUNTIME_WORK_POLL_INTERVAL_MS = 0
const makeScheduler = (behaviour, countCall) => {
  if (behaviour === "unavailable") return undefined
  return (callback) => {
    countCall()
    if (behaviour === "throw-before") throw new Error("scheduler threw before callback")
    if (behaviour === "async-return") {
      nativeSetTimeout(callback, 0)
      healthyTurns++
      return
    }
    callback()
    if (behaviour === "sync-throw-after") throw new Error("scheduler threw after callback")
    healthyTurns++
  }
}
let timer = makeScheduler(timerBehaviour, () => { timerCalls++ })
let __scheduleMacrotask = makeScheduler(macrotaskBehaviour, () => { macrotaskCalls++ })
const globalThis = { get setTimeout() { return timer } }
const workIsPending = () => healthyTurns < requiredTurns
const __napiInstance = { exports: {
  napi_prepare_wasm_env_cleanup_begin: () => true,
  napi_prepare_wasm_env_cleanup_finish: () => {
    if (workIsPending()) throw new Error("finish called while work was pending")
    finishCount++
  },
  napi_wasm_runtime_work_pending: workIsPending,
} }
const __createWasmRuntimePollPace = () => ({})
const __prepareWasmEnvCleanup = () => {}
const __abortWasiDisposalIfThreadCrashed = () => {}
return {
  dispose: __prepareWasmEnvCleanupWithTurns,
  recover: () => {
    timer = makeScheduler("sync-return", () => { timerCalls++ })
    __scheduleMacrotask = makeScheduler("sync-return", () => { macrotaskCalls++ })
  },
  state: () => ({ finishCount, pending: workIsPending(), timerCalls, macrotaskCalls }),
}`,
      );
      const withTimeout = (promise, label) =>
        Promise.race([
          Promise.resolve(promise),
          new Promise((_, reject) =>
            setTimeout(
              () =>
                reject(new Error(`timed out: ${label}`)),
              500,
            ),
          ),
        ]);

      for (const timerBehaviour of behaviours) {
        for (const macrotaskBehaviour of behaviours) {
          for (const requiredTurns of [1, 2]) {
            const label = `${timerBehaviour}/${macrotaskBehaviour}/${requiredTurns}`;
            const harness = createHarness(
              setTimeout,
              timerBehaviour,
              macrotaskBehaviour,
              requiredTurns,
            );
            const selectedBehaviour =
              timerBehaviour === "unavailable"
                ? macrotaskBehaviour
                : timerBehaviour;
            const shouldReject = throwingBehaviours.has(
              selectedBehaviour,
            );

            if (shouldReject) {
              // oxlint-disable-next-line typescript/await-thenable, typescript/no-confusing-void-expression -- Function-created fixture types are opaque to the type-aware linter.
              await expect(
                withTimeout(harness.dispose(), label),
              ).rejects.toThrow();
              expect(harness.state()).toMatchObject({
                finishCount: 0,
                pending: true,
              });
              const failedState = harness.state();
              if (timerBehaviour === "unavailable") {
                expect(failedState.timerCalls, label).toBe(
                  0,
                );
                if (macrotaskBehaviour !== "unavailable") {
                  expect(
                    failedState.macrotaskCalls,
                    label,
                  ).toBe(1);
                }
              } else {
                expect(failedState.timerCalls, label).toBe(
                  1,
                );
                expect(
                  failedState.macrotaskCalls,
                  label,
                ).toBe(0);
              }
              harness.recover();
              await withTimeout(
                harness.dispose(),
                `${label}/retry`,
              );
            } else {
              await withTimeout(harness.dispose(), label);
            }

            const state = harness.state();
            expect(state.finishCount, label).toBe(1);
            expect(state.pending, label).toBe(false);
            if (
              !shouldReject &&
              timerBehaviour === "unavailable"
            ) {
              expect(state.timerCalls, label).toBe(0);
              expect(state.macrotaskCalls, label).toBe(
                requiredTurns,
              );
            } else if (!shouldReject) {
              expect(state.timerCalls, label).toBe(
                requiredTurns,
              );
              expect(state.macrotaskCalls, label).toBe(0);
            }
          }
        }
      }
    }, 10_000);
  }

  test("all scheduler calls use the safe handshake", () => {
    for (const fileName of [
      "aho-corasick.wasi-browser.js",
      "aho-corasick.wasi.cjs",
    ]) {
      expect(
        schedulerCallsOutsideHandshake(read(fileName)),
      ).toEqual([]);
    }

    const unsafeFixture = `
function __yieldWasmRuntimePollTurn() {
  const timer = __scheduleTimer
  timer(() => {}, 1)
}
`;
    expect(
      schedulerCallsOutsideHandshake(unsafeFixture),
    ).toEqual(["timer(() => {}, 1)"]);

    const unsafePromiseFixture = `
function drain() {
  return new Promise((resolve) => {
    __scheduleTimer(resolve, 1)
  })
}
`;
    expect(
      schedulerCallsOutsideHandshake(unsafePromiseFixture),
    ).toEqual(["__scheduleTimer(resolve, 1)"]);

    const unsafeFallbackFixture = `
function __scheduleTimer(callback, delay) {
  const setTimer = globalThis.setTimeout
  try {
    setTimer(callback, delay)
  } catch {
    __scheduleMacrotask(callback)
  }
}
`;
    expect(
      normalizeGeneratedLoader(unsafeFallbackFixture),
    ).not.toContain("catch {");
  });

  test("every generated Worker construction shares workerData", () => {
    for (const fileName of [
      "aho-corasick.wasi-browser.js",
      "aho-corasick.wasi.cjs",
    ]) {
      expect(
        workerConstructionsWithoutSharedData(
          read(fileName),
        ),
      ).toEqual([]);
    }

    const missingFallbackData = `
const workerData = { crashFlag, crashReport }
const workerOptions = { workerData }
try {
  new Worker(path, workerOptions)
} catch {
  new Worker(path)
}
`;
    expect(
      workerConstructionsWithoutSharedData(
        missingFallbackData,
      ),
    ).toEqual(["new Worker(path)"]);
  });

  test("the execArgv retry preserves crash workerData", () => {
    const source = read("aho-corasick.wasi.cjs");
    const getExecArgv = extractFunction(
      source,
      "__getWasiWorkerExecArgv",
    );
    const identifiesInvalidArgument = extractFunction(
      source,
      "__isInvalidWasiWorkerExecArgv",
    );
    const removeInvalidArgument = extractFunction(
      source,
      "__removeInvalidWasiWorkerExecArgv",
    );
    const createWorker = extractFunction(
      source,
      "__createWasiWorker",
    );
    const attempts = [];
    // oxlint-disable-next-line typescript/no-implied-eval -- Executes the worker factory extracted from the real generated loader.
    const run = Function(
      "attempts",
      `${getExecArgv}
${identifiesInvalidArgument}
${removeInvalidArgument}
${createWorker}
const __hostRoot = "/host"
const __rootDir = "/"
const __wasiThreadCrashFlag = new Int32Array(new SharedArrayBuffer(4))
const __wasiThreadCrashReport = new SharedArrayBuffer(64)
const __wasiAddonCrashFlag = new Int32Array(new SharedArrayBuffer(4))
const process = { env: {}, execArgv: ["--invalid-worker-flag"] }
function Worker(filename, options) {
  attempts.push({ filename, options })
  if (attempts.length === 1) {
    const error = new Error("Initiated Worker with invalid execArgv flags: --invalid-worker-flag")
    error.code = "ERR_WORKER_INVALID_EXEC_ARGV"
    throw error
  }
  return { filename, options }
}
return __createWasiWorker("worker.mjs")
`,
    );

    const worker = run(attempts);
    expect(attempts).toHaveLength(2);
    expect(attempts[0].options.workerData).toBe(
      attempts[1].options.workerData,
    );
    expect(worker.options.workerData).toMatchObject({
      hostRoot: "/host",
      rootDir: "/",
      crashFlag: expect.any(Int32Array),
      crashReport: expect.any(SharedArrayBuffer),
      addonCrashFlag: expect.any(Int32Array),
    });
    expect(worker.options.execArgv).toEqual([]);
  });

  test("published runtime versions match the build manifest", () => {
    const rootManifest = JSON.parse(read("package.json"));
    const manifests = ["package.json"];
    for (const directory of ["npm", "wasm"]) {
      for (const entry of readdirSync(
        new URL(directory, root),
        {
          withFileTypes: true,
        },
      )) {
        if (entry.isDirectory()) {
          manifests.push(
            `${directory}/${entry.name}/package.json`,
          );
        } else if (entry.name === "package.json") {
          manifests.push(`${directory}/package.json`);
        }
      }
    }
    const expected = rootManifest.devDependencies;
    for (const manifestPath of manifests) {
      const manifest = JSON.parse(read(manifestPath));
      const declared = {
        ...manifest.devDependencies,
        ...manifest.dependencies,
      };
      for (const packageName of [
        ...runtimePackages,
        "emnapi",
      ]) {
        if (declared[packageName] === undefined) continue;
        expect(
          declared[packageName],
          `${manifestPath}: ${packageName}`,
        ).toBe(expected[packageName]);
      }
    }
  });

  test("keeps artifact metadata on the first line", () => {
    for (const fileName of [
      "aho-corasick.wasi-browser.js",
      "aho-corasick.wasi.cjs",
    ]) {
      const lines = read(fileName).split("\n");
      const metadata = lines.find((line) =>
        line.startsWith("// napi-rs-artifact-metadata:"),
      );
      if (metadata !== undefined) {
        expect(lines[0]).toBe(metadata);
      }
    }
  });
});
